"""Rebuild a labelled, self-contained synthetic rehearsal and team worksheets."""
from pathlib import Path
import json
import sys
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from neuratwin.halo_api import obtain
from neuratwin.halo_evidence import predict, score_prediction, plan, rows_for
from neuratwin.halo_api import Context

ROOT=Path(__file__).resolve().parents[1];WEB=ROOT/'web'
snap=obtain('transformer','overload',148)
proof=predict(snap,15);proof['horizon_min']=15
score=score_prediction(proof,rows_for(Context(mode='transformer',scenario='overload',cursor=151)))
options=plan(snap,60,3,[])
data={'source':'PRECOMPUTED SYNTHETIC EXAMPLE — NOT LIVE HARDWARE','origin':proof['origin'],
      'load_pct':snap['metrics']['load_pct'],'oil_c':snap['current']['oil_c'],'hotspot_c':snap['current']['estimated_hotspot_c'],
      'score':score,'plan':{k:options[k] for k in ['recommendation','limit_c','note']}}
style='''body{font:17px/1.6 system-ui,sans-serif;background:#f4f3ee;color:#263b3e;margin:0}main{max-width:1120px;margin:auto;padding:36px}header{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;border-bottom:1px solid #d2d7cc;padding-bottom:20px}h1{font-size:clamp(36px,6vw,68px);letter-spacing:-.05em;line-height:1.05}h2{font-size:27px;line-height:1.2}p{max-width:900px}.tag{font-size:12px;letter-spacing:.08em;color:#a24320;font-weight:700}.card{background:#fffef8;border:1px solid #d5d7cd;padding:26px;border-radius:12px;margin:18px 0}button,.button{font:inherit;padding:12px 20px;border:1px solid #c7ccbf;border-radius:7px;background:#fff;color:#263b3e;cursor:pointer;text-decoration:none;display:inline-block;margin:5px}button.primary{background:#ae4b21;color:#fff;border-color:#ae4b21}button:focus-visible{outline:3px solid #366481}button:disabled{opacity:.4;cursor:default}.facts{display:flex;gap:30px;flex-wrap:wrap}.facts strong{font-size:38px;display:block}.facts span{font-size:13px;color:#61716e}.notice{padding:16px;background:#eee5d2;border-left:4px solid #b95124}svg{width:100%;height:auto}footer{display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap}.muted{color:#61716e;font-size:14px}table{border-collapse:collapse;width:100%}td,th{border-bottom:1px solid #d2d7cc;text-align:left;padding:12px}input[type=text]{padding:10px;width:90%;border:1px solid #c7ccbf}li{margin:12px 0}@media(max-width:600px){main{padding:20px}.card{padding:18px}}@media print{button,.button{display:none}body{background:#fff}main{padding:0}h1{font-size:32px}.card{break-inside:avoid}}'''
def page(title,body,script=''):
    return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>'+style+'</style><main>'+body+'</main>'+script+'</html>'

body='''<header><b>NeuraTwin Halo / Neura Rangers</b><span class="tag">OFFLINE REHEARSAL · PRECOMPUTED SYNTHETIC DATA</span></header><p class="tag" id="step"></p><h1 id="title"></h1><div id="content"></div><footer><button id="prev">← Previous</button><span id="position"></span><button id="next" class="primary">Next →</button></footer><p class="muted">This file works without a network or server. Its stored example is not a new prediction, a physical recording, or evidence of field performance. Nothing here sends equipment commands.</p>'''
script='''<script>const D=DATA;let step=0;const $=id=>document.getElementById(id),f=v=>v.toFixed(2);const screens=[
['Inspect the asset.',`<p>The actual application connects measurements, conditional models and maintenance evidence. This portable example uses the same synthetic overload fixture.</p><div class="card facts"><div><span>LOAD</span><strong>${f(D.load_pct)}%</strong></div><div><span>SIMULATED OIL</span><strong>${f(D.oil_c)} °C</strong></div><div><span>INFERRED HOT-SPOT</span><strong>${f(D.hotspot_c)} °C</strong></div></div><p class="notice">Bench surface temperature is a different measurement. It is never presented as transformer oil or winding temperature.</p>`],
['Ask what explains the change.',`<div class="card"><h2>Observed loading exceeds the configured rating.</h2><p>Compare expected response against observations, then check sensor confidence and loading before naming a fault.</p><ul><li>Measurement issue? Compare against an independent reference.</li><li>Unexpected heating? Check loading, ambient and heat rejection.</li><li>Missing data? Withhold the inference.</li></ul></div><p>Hypotheses remain distinct from confirmed physical findings.</p>`],
['Compare a constrained action.',`<div class="card"><span class="tag">CONDITIONAL MODEL STUDY / 60 MINUTES</span><h2>${D.plan.recommendation.label}</h2><p>Delay: ${D.plan.recommendation.delay_min} min. Parameter-sensitivity peak: ${f(D.plan.recommendation.peak_c)} °C, against the configured ${f(D.plan.limit_c)} °C limit.</p><p>${D.plan.note}</p></div><p class="notice">The live software now also checks recent forecast performance. It withholds unqualified bench recommendations; a study does not authorise a physical intervention.</p>`],
['Freeze first. Reveal second.',`<div class="card"><h2>Oil-temperature prediction versus later synthetic observations</h2><svg id="plot" viewBox="0 0 900 260" role="img" aria-label="Precomputed frozen forecast and later simulated observations"></svg><p>Orange: observed fixture · Blue: frozen forecast</p><div class="facts"><div><span>MODEL MAE</span><strong>${f(D.score.all_observations.mae_c)} °C</strong></div><div><span>PERSISTENCE MAE</span><strong>${f(D.score.all_observations.persistence_mae_c)} °C</strong></div><div><span>OBSERVATIONS</span><strong>${D.score.all_observations.count}</strong></div></div></div><p>This stored example illustrates the workflow. In the application, freeze before advancing the selected recording. Poorer model results remain visible.</p>`],
['Leave a defensible record.',`<div class="card"><h2>The case travels with its evidence.</h2><p>Readings → hypotheses → proposed action → frozen forecast → observed outcome → maintenance follow-up.</p><ul><li>Case JSON retains model versions, inputs and sources.</li><li>The printable report makes the case readable.</li><li>Checksums help detect changes, not certify measurement truth.</li></ul><button id="save">Save this synthetic example JSON</button></div><p class="notice">Actual commissioning, real sensor recordings and field validation are separate work. No demonstrated remaining useful life or physical repair is claimed.</p>`]
];function draw(){const s=screens[step];$('step').textContent='THE DECISION / '+String(step+1).padStart(2,'0');$('title').textContent=s[0];$('content').innerHTML=s[1];$('prev').disabled=step===0;$('next').disabled=step===4;$('position').textContent=(step+1)+' / 5';if(step===3){const a=D.score.samples,v=a.flatMap(p=>[p.actual_c,p.predicted_c]),lo=Math.min(...v)-.5,hi=Math.max(...v)+.5,y=t=>220-(t-lo)/(hi-lo)*180;let h='';for(let i=0;i<4;i++){let t=lo+(hi-lo)*i/3;h+=`<line x1="65" x2="870" y1="${y(t)}" y2="${y(t)}" stroke="#d3d6cd"/><text x="5" y="${y(t)+5}" font-size="16">${t.toFixed(1)}</text>`;}for(const [key,color] of [['actual_c','#b84e1e'],['predicted_c','#35648a']])h+=`<polyline points="${a.map((p,i)=>`${65+i*805/(a.length-1)},${y(p[key])}`).join(' ')}" stroke="${color}" stroke-width="4" fill="none"/>`;h+='<text x="65" y="250">+5 min</text><text x="810" y="250">+15 min</text>';$('plot').innerHTML=h;}if(step===4)$('save').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(D,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='synthetic-example.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};}$('prev').onclick=()=>{step--;draw()};$('next').onclick=()=>{step++;draw()};document.addEventListener('keydown',e=>{if(e.key==='ArrowRight'&&step<4){step++;draw()}if(e.key==='ArrowLeft'&&step>0){step--;draw()}});draw();</script>'''.replace('DATA',json.dumps(data,ensure_ascii=False))
(WEB/'halo-fallback.html').write_text(page('NeuraTwin Halo · Offline rehearsal',body,script),encoding='utf-8')

checks=['Technician identifies the actual primary, secondary and tap; unexplained resistance asymmetry resolved.','Technician records protection, enclosure, insulation, strain relief and earth arrangements.','Actual ESP32 chip, pins, relay polarity/reset behaviour and sensor interfaces independently verified.','Software commissioning holds reviewed against real records. Physical K4 remains locked.','Record independent secondary-voltage, current and surface-temperature references; enter separate calibration records.','Acquire a timestamped physical session through the existing USB bridge after the bench is approved.','Observe only permitted load changes within reviewed ratings; record actual voltage/current response and conditions.','Record any warning, incident, inspection and follow-up; an acknowledgement does not prove a relay contact opened.','Rehearse loss of the data link without assuming software protection substitutes for independent protection.','Export the physical session and acceptance case. Keep physical measurements separate from synthetic examples.']
body='<header><b>NeuraTwin Halo / Hardware acceptance worksheet</b><span class="tag">UNCOMPLETED / REQUIRES REAL OBSERVATIONS</span></header><h1>Verify the bench.<br>Record the evidence.</h1><p class="notice">No mains test is authorised by this worksheet. Transformer winding identity and electrical protection remain subject to qualified review. Do not use the architecture illustration as a wiring diagram.</p><p>Reviewer: ____________________ Date: ____________________ Bench ID: ____________________</p>'+''.join('<div class="card"><label><input type="checkbox"> '+c+'</label><p>Evidence reference / observation: <input type="text" aria-label="Evidence reference"></p></div>' for c in checks)+'<p>Required channels: secondary V RMS, combined load A RMS, transformer surface °C. Ambient must be independently observed or use a verified probe. Oil, winding hot-spot, DGA and insulation life are not bench measurements.</p><button onclick="window.print()">Print worksheet</button>'
(WEB/'halo-bench-checklist.html').write_text(page('Halo · Hardware acceptance worksheet',body),encoding='utf-8')
body='''<header><b>NeuraTwin Halo / Presenter notes</b><span class="tag">3-MINUTE SOFTWARE DEMONSTRATION</span></header><h1>One asset.<br>One inspectable decision.</h1><table><tr><th>Time</th><th>Show</th><th>Say</th></tr><tr><td>0:00–0:30</td><td>Inspect</td><td>“This source is labelled. Our physical bench measures surface temperature; the distribution study models oil and winding separately.”</td></tr><tr><td>0:30–1:00</td><td>Investigate</td><td>“Here is the deviation, the evidence supporting it, and the next physical check. Missing data stays missing.”</td></tr><tr><td>1:00–1:40</td><td>Compare</td><td>“We search discrete actions under constraints and preserve rejected alternatives. Recent model underperformance can withhold recommendations.”</td></tr><tr><td>1:40–2:30</td><td>Verify</td><td>“We freeze a measurable-target forecast before revealing later readings, then compare with persistence. These observations are simulated.”</td></tr><tr><td>2:30–3:00</td><td>Export</td><td>“A maintenance decision carries its sources, assumptions, model version and follow-up evidence.”</td></tr></table><h2>Fallback rehearsal</h2><ol><li>Start the local server with Wi-Fi unavailable. Local replay should still work; language-model availability depends on its installed assets.</li><li>If the server is unavailable, open the downloaded halo-fallback.html. Its banner explicitly identifies a stored synthetic example.</li><li>If the sensor is disconnected, show disconnected/unavailable and switch deliberately to labelled replay. Never silently substitute simulated telemetry.</li><li>Use halo-rehearsal.mp4 if live browsing is unavailable. It is a captioned software walkthrough, not footage of working hardware.</li></ol><h2>Bring to the event</h2><p>Laptop and charger, the downloaded kit, source repository, recorded acceptance results and actual physical telemetry if available, verified circuit documentation, and a qualified reviewer’s completed hardware checks.</p><p class="notice">Do not claim 100% accuracy, guaranteed failure prediction, actual remaining life, automatic safe mains control or a physical repair based on replay.</p><button onclick="window.print()">Print presenter notes</button>'''
(WEB/'halo-demo-script.html').write_text(page('Halo · Presenter notes',body),encoding='utf-8')

nodes=[(40,150,'PHYSICAL BENCH','Verified source + permitted loads','Voltage / current / surface sensors'),(425,150,'ACQUISITION','ESP32 → authenticated USB bridge','Timestamp · raw quality · calibration'),(810,150,'LOCAL SOFTWARE','FastAPI + SQLite','Source-separated immutable readings'),(40,430,'REFERENCE & FORECAST','Expected response · hypotheses','Qualification against persistence'),(425,430,'DECISION SUPPORT','Conditional intervention search','Uncertainty and missing-data holds'),(810,430,'MAINTENANCE EVIDENCE','Inspection → follow-up → verification','Case JSON · printable report · hashes')]
svg='<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="760" viewBox="0 0 1200 760"><rect width="1200" height="760" fill="#f4f3ee"/><g font-family="Arial,sans-serif" fill="#263b3e"><text x="40" y="65" font-size="34" font-weight="bold">NeuraTwin Halo / system architecture</text><text x="40" y="104" font-size="18">Data flow only. Not a circuit or wiring diagram. Unknown hardware connections remain unresolved.</text>'
for x,y,title,line1,line2 in nodes:
    svg+=f'<rect x="{x}" y="{y}" width="345" height="165" rx="10" fill="#fffef8" stroke="#c8cdbd"/><rect x="{x}" y="{y}" width="345" height="5" fill="#ae4b21"/><text x="{x+20}" y="{y+40}" font-size="17" font-weight="bold">{title.replace("&","&amp;")}</text><text x="{x+20}" y="{y+83}" font-size="16">{line1}</text><text x="{x+20}" y="{y+115}" font-size="15">{line2}</text>'
svg+='</g><g fill="none" stroke="#667762" stroke-width="3"><path d="M385 232H425m-12-8 12 8-12 8M770 232H810m-12-8 12 8-12 8M982 315V365H210V430m-8-12 8 12 8-12M385 512H425m-12-8 12 8-12 8M770 512H810m-12-8 12 8-12 8"/></g><text x="40" y="660" font-family="Arial" font-size="18" fill="#9b411f">Replay is a separate software input. Physical K4 is locked; no guided-demo step controls hardware.</text><text x="40" y="702" font-family="Arial" font-size="16" fill="#586b65">Hardware identity, sensor conditioning, calibration and independent protection require actual qualified review.</text></svg>'
(WEB/'halo-architecture.svg').write_text(svg,encoding='utf-8')
print('Built four self-contained demonstration/acceptance assets from explicitly synthetic data. The video is built separately from browser screenshots.')
